```python
def num_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

S = 0

for n in range(20, 2019, 20):
    if num_divisors(n) == 20:
        S += n

result = S // 20
print(result)
```
